-- DALAN v0.4-v0.6: additive, scoped to DALAN Neon database only.
-- Applying this file to CLEAR or ASPECT is prohibited.
CREATE TABLE IF NOT EXISTS public.dalan_staff (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),display_name varchar(90) NOT NULL,email varchar(180) NOT NULL UNIQUE,password_hash varchar(220) NOT NULL,role varchar(25) NOT NULL CHECK(role IN ('super_admin','safety_officer','transport_admin','operator_manager','viewer')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS dalan_one_initial_super_admin ON public.dalan_staff ((role)) WHERE role='super_admin';
CREATE TABLE IF NOT EXISTS public.dalan_staff_sessions (token_hash char(64) PRIMARY KEY,staff_id uuid NOT NULL REFERENCES public.dalan_staff(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS public.dalan_staff_attempts (email varchar(180) PRIMARY KEY,failed_count integer NOT NULL DEFAULT 0,locked_until timestamptz);
CREATE TABLE IF NOT EXISTS public.dalan_access_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_staff_id uuid REFERENCES public.dalan_staff(id) ON DELETE SET NULL,action varchar(80) NOT NULL,subject_id uuid,description varchar(160),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS admin_visibility boolean NOT NULL DEFAULT false;
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS admin_consent_at timestamptz;
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS checkin_minutes integer NOT NULL DEFAULT 15;
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS last_checkin_at timestamptz;
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS next_checkin_at timestamptz;
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS assistance_status varchar(20) NOT NULL DEFAULT 'none';
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS assistance_requested_at timestamptz;
ALTER TABLE public.dalan_trip_shares ADD COLUMN IF NOT EXISTS assistance_note varchar(300);
CREATE TABLE IF NOT EXISTS public.dalan_transport_routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),route_code varchar(35) NOT NULL UNIQUE,route_name varchar(160) NOT NULL,mode varchar(25) NOT NULL CHECK (mode IN ('tricycle','jeepney','bus','van','walking','other')),origin_label varchar(150),destination_label varchar(150),verification_status varchar(16) NOT NULL DEFAULT 'draft' CHECK (verification_status IN ('draft','verified','suspended')),source_reference text,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK (verification_status!='verified' OR (source_reference IS NOT NULL AND verified_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS public.dalan_fare_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),route_id uuid REFERENCES public.dalan_transport_routes(id),mode varchar(25) NOT NULL CHECK(mode IN ('tricycle','jeepney','bus','van','other')),passenger_type varchar(25) NOT NULL CHECK(passenger_type IN ('regular','student','senior','pwd')),fare_kind varchar(25) NOT NULL CHECK(fare_kind IN ('flat','per_km','special_estimate')),distance_from_km numeric(8,2),distance_to_km numeric(8,2),amount_php numeric(12,2) NOT NULL CHECK (amount_php>=0),verification_status varchar(16) NOT NULL DEFAULT 'draft' CHECK(verification_status IN ('draft','verified','suspended')),source_reference text,effective_from date,effective_to date,notes varchar(300),created_at timestamptz NOT NULL DEFAULT now(),CHECK (verification_status!='verified' OR (source_reference IS NOT NULL AND effective_from IS NOT NULL)),CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from),CHECK (distance_to_km IS NULL OR distance_from_km IS NULL OR distance_to_km>=distance_from_km));
CREATE TABLE IF NOT EXISTS public.dalan_operator_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization varchar(130) NOT NULL,contact_email varchar(180) NOT NULL,transport_mode varchar(25) NOT NULL CHECK(transport_mode IN ('tricycle','jeepney','bus','van','other')),route_notes varchar(320),vehicle_body_number varchar(40),consent_at timestamptz NOT NULL DEFAULT now(),status varchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reviewed_by uuid REFERENCES public.dalan_staff(id),created_at timestamptz NOT NULL DEFAULT now());
